use std::{env,fs};use mushroom_solar::weather::{parse_nasa_power_hourly_csv,check_declared_interval,summarize_qc};
fn main(){let p=env::args().nth(1).expect("usage: development-weather-qc FILE");let s=fs::read_to_string(&p).expect("read weather file");let (r,mut q)=parse_nasa_power_hourly_csv(&s).expect("NASA POWER ingestion failed");q.extend(check_declared_interval(&r,3600).expect("interval QC"));let z=summarize_qc(&r,&q,Some(3600));println!("dataset=NASA_POWER_SINGAPORE_2024_DEVELOPMENT");println!("parsed_samples={}",r.len());println!("expected_samples=8784");println!("issues={}",q.len());println!("duplicate_timestamps={}",z.duplicate_timestamps);println!("nonmonotonic_timestamps={}",z.nonmonotonic_timestamps);println!("negative_irradiance_values={}",z.negative_irradiance_values);println!("temporal_gap_missing_samples={}",z.temporal_gap_missing_samples.unwrap_or(usize::MAX));println!("longest_gap_s={}",z.longest_gap_s.unwrap_or(0));assert_eq!(r.len(),8784,"2024 leap-year hourly coverage incomplete");assert!(q.is_empty(),"development dataset has QC issues: {q:?}");}